{
  "name": "@vymalo/opencode-core-otel",
  "version": "0.20.2",
  "description": "Shared OpenTelemetry engine (exporters, recorder, resource, token-source seam) for the @vymalo OpenCode plugin suite.",
  "license": "MIT",
  "author": "vymalo contributors",
  "homepage": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit.git",
    "directory": "packages/opencode-core-otel"
  },
  "bugs": {
    "url": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit/issues"
  },
  "keywords": [
    "opencode",
    "opentelemetry",
    "otel",
    "otlp",
    "observability",
    "telemetry",
    "tracing",
    "metrics",
    "cost-tracking",
    "gen-ai",
    "llm"
  ],
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./lib": {
      "types": "./dist/lib.d.ts",
      "import": "./dist/lib.js"
    },
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opentelemetry/api": "^1.9.1",
    "@opentelemetry/api-logs": "^0.222.0",
    "@opentelemetry/core": "^2.11.0",
    "@opentelemetry/exporter-logs-otlp-proto": "^0.222.0",
    "@opentelemetry/exporter-metrics-otlp-proto": "^0.222.0",
    "@opentelemetry/exporter-trace-otlp-proto": "^0.222.0",
    "@opentelemetry/resources": "^2.11.0",
    "@opentelemetry/sdk-logs": "^0.222.0",
    "@opentelemetry/sdk-metrics": "^2.11.0",
    "@opentelemetry/sdk-trace": "^2.11.0"
  },
  "devDependencies": {
    "vite": "^8.3.0",
    "vitest": "^5.0.1"
  },
  "scripts": {
    "build": "node ../../scripts/build-package.mjs",
    "lint": "biome lint .",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "coverage": "vitest run --coverage",
    "format": "biome format --write .",
    "format:check": "biome format ."
  }
}
